import re

def cmp_semver(a, b):
    def parse_version(v):
        # Remove build metadata
        main_part = v.split('+')[0]
        # Split version and pre-release
        parts = main_part.split('-')
        version_numbers = parts[0].split('.')
        pre_release = parts[1] if len(parts) > 1 else None

        # Parse major.minor.patch
        nums = []
        for n in version_numbers:
            try:
                nums.append(int(n))
            except ValueError:
                nums.append(n)

        # Parse pre-release identifiers
        pre_ids = []
        if pre_release is not None:
            for item in pre_release.split('.'):
                if item.isdigit():
                    pre_ids.append((0, int(item))) # 0 for numeric
                else:
                    pre_ids.append((1, item))       # 1 for alphanumeric

        return nums, pre_ids

    v1_nums, v1_pre = parse_version(a)
    v2_nums, v2_pre = parse_version(b)

    # Compare major.minor.patch
    for n1, n2 in zip(v1_nums, v2_nums):
        if n1 < n2: return -1
        if n1 > n2: return 1

    # If lengths differ in major.minor.patch (e.g. 1.0 vs 1.0.1)
    if len(v1_nums) != len(v2_nums):
        return -1 if len(v1_nums) < len(v2_nums) else 1

    # Pre-release logic: version WITH pre-release sorts BEFORE version WITHOUT
    # If one has pre-release and other doesn't, the one WITH it is smaller
    has_pre1 = v1_pre is not None
    has_pre2 = v2_pre is not None

    if has_pre1 != has_pre2:
        return -1 if has_pre1 else 1

    if has_pre1 and has_pre2:
        for p1, p2 in zip(v1_pre, v2_pre):
            # p is (type_priority, value)
            if p1[0] != p2[0]:
                return -1 if p1[0] < p2[0] else 1
            if p1[1] < p2[1]: return -1
            if p1[1] > p2[1]: return 1

        if len(v1_pre) != len(v2_pre):
            return -1 if len(v1_pre) < len(v2_pre) else 1

    return 0
