import re

def parse_range(header, size):
    if not header or not isinstance(header, str):
        return None

    # Extract the bytes part (e.g., "bytes=0-499, 500-")
    match = re.search(r'bytes=([^,]+)', header)
    if not match:
        return None

    raw_ranges = match.group(1).split(',')
    results = []
    any_satisfiable = False

    for r in raw_ranges:
        r = r.strip()
        if not r:
            continue

        try:
            if r.startswith('-'):
                # Handle suffix range like -500
                suffix_val = int(r[1:].strip())
                start = max(0, size - suffix_val)
                end = size - 1
                if start < size:
                    results.append((start, end))
                    any_satisfiable = True
            else:
                # Handle standard range like 0-499 or 500-
                parts = r.split('-')
                if len(parts) == 1:
                    # Single value like "500"
                    start = int(parts[0].strip())
                    end = start
                else:
                    start_str = parts[0].strip()
                    end_str = parts[1].strip()

                    start = int(start_str) if start_str else 0
                    end = int(end_str) if end_str else size - 1

                # Clamp end to size
                end = min(end, size - 1)

                if start < size and start <= end:
                    results.append((start, end))
                    any_satisfiable = True
        except ValueError:
            return None

    return results if any_satisfiable else None
