        # but a more robust way is to check if the joined tokens match the input
        pass

    def get_precedence(op):
        if op in ('+', '-'): return 1
        if op in ('*', '/', '%'): return 2
        if op == '**': return 3
        return 4

    def apply_op(operators, values):
        op = operators.pop()
        right = values.pop()
        left = values.pop()
        if op == '+': values.append(left + right)
        elif op == '-': values.append(left - right)
        elif op == '*': values.append(left * right)
        elif op == '/': 
            if right == 0: raise ValueError("Division by zero")
            values.append(left / right)
        elif op == '%': values.append(left % right)
        elif op == '**': values.append(left ** right)
        elif op == 'u+': values.append(+right)
        elif op == 'u-': values.append(-right)

    def shunting_yard(tokens):
        output = []
        operators = []

        i = 0
        while i < len(tokens):
            token = tokens[i]

            if re.match(r'^\d+\.\d+$|^\d+$', token):
                output.append(float(token) if '.' in token else int(token))
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    output.append(operators.pop())
                if not operators: raise ValueError("Mismatched parentheses")
                operators.pop()
            else:
                # Handle Unary Operators
                # A unary operator is<image|>                # at the start or after an operator/opening paren
                if token in ('+', '-') and (i == 0 or tokens[i-1] in ('+', '-', '*', '/', '%', '**', '(')):
                    # Look ahead to see if it's unary
                    # In this grammar, unary is highest precedence
                    # We mark it as 'u+' or 'u-'
                    op = 'u' + token
                    while operators and operators[-1] != '(' and get_precedence(operators[-1]) < 4:
                        output.append(operators.pop())
                    operators.append(op)
                else:
