                    while operators and operators[-1] != '(' and (
                        get_precedence(operators[-1]) > get_precedence(token) or
                        (get_precedence(operators[-1]) == get_precedence(token) and token != '**')
                    ):
                        output.append(operators.pop())
                    operators.append(token)
            i += 1

        while operators:
            output.append(operators.pop())
        return output

    # Refined Shunting Yard to handle specific precedence rules
    # Precedence: + - (1), * / % (2), ** (3), Unary (4)
    # ** is right associative

