                output.append(float(t) if '.' in t else int(t))
            elif t == '(':
                ops.append(t)
            elif t == ')':
                while ops and ops[-1] != '(':
                    output.append(ops.pop())
                if not ops: raise ValueError("Mismatched parentheses")
                ops.pop()
            else:
                prec = get_precedence(t)
                while ops and ops[-1] != '(':
                    top_prec = get_precedence(ops[-1])
                    if top_prec > prec or (top_prec == prec and t != '**'):
                        output.append(ops.pop())
                    else:
                        break
                ops.append(t)

        while ops:
            output.append(ops.pop())

        # Evaluation
        values = []
        for t in output:
            if isinstance(t, (int, float)):
                values.append(t)
            else:
                if t.startswith('u'):
                    r = values.pop()
                    values.append(-r if t == 'u-' else r)
                else:
                    r = values.pop()
                    l = values.pop()
