import heapq

def shortest_path(graph, src, dst):
    if src == dst:
        return (0, [src])

    # Priority Queue: (cost, num_edges, node)
    pq = [(0, 0, src)]
    # dists[node] = (cost, num_edges)
    dists = {src: (0, 0)}
    # parents[node] = parent_node
    parents = {src: None}

    while pq:
        d, e, u = heapq.heappop(pq)

        if (d, e) > dists.get(u, (float('inf'), float('inf'))):
            continue

        if u == dst:
            continue

        for v, w in graph.get(u, []):
            new_d = d + w
            new_e = e + 1

            if v not in dists or (new_d, new_e) < dists[v]:
                dists[v] = (new_d, new_e)
                parents[v] = u
                heapq.heappush(pq, (new_d, new_e, v))
            elif (new_d, new_e) == dists[v]:
                if u < parents[v]:
                    parents[v] = u

    if dst not in dists:
        return (None, [])

    path = []
    curr = dst
    while curr is not None:
        path.append(curr)
        curr = parents[curr]
    return (dists[dst][0], path[::-1])
