    def __init__(self):
        self.cells = {}  # cell_id -> value (int or str)
        self.cache = {}  # cell_id -> computed_value
        self.dependencies = {}  # cell_id -> set of cell_ids it depends on
        self.reverse_deps = {}  # cell_id -> set of cell_ids that depend on it

    def _parse_formula(self, formula):
        if not formula.startswith('='):
            return None
        expr = formula[1:]
        tokens = re.findall(r'[A-Z]+\d+|[0-9]+|[\+\-\*]', expr)

        # Convert tokens to internal representation
        parsed_tokens = []
        for t in tokens:
            if t.isdigit():
                parsed_tokens.append(('num', int(t)))
            elif t[0].isalpha():
                parsed_tokens.append(('ref', t))
            else:
                parsed_tokens.append(('op', t))
        return parsed_tokens

    def _evaluate(self, cell_id):
        val = self.cells.get(cell_id, 0)
        if not isinstance(val, str) or not val.startswith('='):
            return val

        tokens = self._parse_formula(val)
        # Standard Shunting-yard or simple recursive descent for + - *
        # Since we need to handle precedence, we'll use a simple stack-based approach
        def compute_simple_expr(tokens_list):
            # Handle * first
            stack = []
            i = 0
            while i < len(tokens_list):
                t = tokens_list[i]
                if t[0] == 'op' and t[1] == '*':
                    left = stack.pop()
                    right = tokens_list[i+1]
                    # right could be ref or num
                    r_val = self.get(right[1]) if right[0] == 'ref' else right[1]
                    stack.append(left * r_val)
                    i += 2
                else:
                    if t[0] == 'ref':
                        stack.append(self.get(t[1]))
                    elif t[0] == 'num':
                        stack.append(t[1])
                    else:
                        stack.append(t)
                    i += 1

            # Handle + and -
            res = stack[0]
            i = 1
            while i < len(stack):
                op = stack[i]
                val = stack[i+1]
                if op == '+': res += val
                elif op == '-': res -= val
                i += 2
            return res

        return compute_simple_expr(tokens)

    def set(self, cell, value):
        # Check for cycles
        new_deps = set()
        if isinstance(value, str) and value.startswith('='):
            tokens = self._parse_formula(value)
            for t in tokens:
                if t[0] == 'ref':
                    new_deps.add(t[1])

        # Cycle detection using DFS
        temp_deps = self.dependencies.get(cell, set())
        temp_deps.update(new_deps)

        visited = set()
        def has_cycle(u):
            visited.add(u)
            for v in self.dependencies.get(u, set()):
                if v == cell: return True
                if v not in visited:
