                self.reverse_deps[old_dep].remove(cell)

        for new_dep in new_deps:
            if new_dep not in self.reverse_deps:
                self.reverse_deps[new_dep] = set()
            self.reverse_deps[new_dep].add(cell)

        # Invalidate cache
        self._invalidate_cache(cell)

    def _invalidate_cache(self, cell_id):
        if cell_id in self.cache:
            del self.cache[cell_id]
        for dependent in self.reverse_deps.get(cell_id, []):
