function debounce(fn, wait, options = {}) {
  let timeoutId = null;
  let lastResult;
  let lastArgs;
  let lastContext;
  let lastCallTime = 0;

  const leading = !!options.leading;
  const trailing = !!options.trailing !== false;

  function invoke() {
    const args = lastArgs;
    const context = lastContext;
    lastResult = fn.apply(context, args);
    lastArgs = null;
    lastContext = null;
    return lastResult;
  }

  const debounced = function(...args) {
    lastArgs = args;
    lastContext = this;
    const now = Date.now();
    const isInvoked = leading && !timeoutId;

    if (timeoutId) {
      clearTimeout(timeoutId);
    }

    if (isInvoked) {
      invoke();
    }

    timeoutId = setTimeout(() => {
      timeoutId = null;
      if (trailing && lastArgs !== null) {
        invoke();
      }
    }, wait);

    return lastResult;
  };

  debounced.cancel = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
    }
    timeoutId = null;
    lastArgs = null;
    lastContext = null;
  };

  debounced.flush = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
    if (lastArgs !== null) {
      invoke();
    }
    return lastResult;
  };

  return debounced;
}

