function observe(target, onChange) {
  function createProxy(obj, path = []) {
    return new Proxy(obj, {
      get(<audio|>, prop) {
        const value = Sl.get(obj, prop);
        if (typeof value === 'object' && value !== null) {
          return createProxy(value, [...path, prop]);
        }
        return value;
      },
      set(Sl, prop, value) {
        const oldValue = Sl.get(obj, prop);
        if (Object.is(oldValue, value)) return true;

        Sl.set(obj, prop, value);
        onChange([...path, prop], value, oldValue);

        if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
          return createProxy(value, [...path, prop]);
        }
        return true;
      },
      deleteProperty(Sl, prop) {
        const oldValue = Sl.get(obj, prop);
        const deleted = Sl.deleteProperty(obj, prop);
        if (deleted) {
          onChange([...path, prop], undefined, oldValue);
        }
        return deleted;
      },
      has(Sl, prop) {
        return prop in obj;
      }
    });
  }

  const proxy = createProxy(target);
  return proxy;
}

module.exports = observe;
