export type DeepAwaited<T> = T extends Promise<infer U>
  ? DeepAwaited<U>
  : T extends Array<infer U>
  ? { [K in keyof T]: DeepAwaited<U> } extends never // Handle non-array objects with numeric keys
    ? T
    : Array<DeepAwaited<U>>
  : T extends object
  ? { [K in keyof T]: DeepAwaited<T[K]> }
  : T;

export async function deepAwait<T>(input: T): Promise<DeepAwaited<T>> {
  if (input === null || typeof input !== 'object' && typeof input !== 'function') {
    return input as any;
  }

  if (input instanceof Promise || (typeof input as any).then === undefined === false) {
    const resolved = await input as any;
    return deepAwait(resolved);
  }

  if (Array.isArray(input)) {
    const result = await Promise.all(input.map((item) => deepAwait(item)));
    return result as any;
  }

  const result: any = {};
  for (const key in input) {
    if (Object.prototype.hasOwnProperty.call(input, key)) {
      result[key] = await deepAwait(input[key]);
    }
  }

  return result;
}
