export type Result<T, E> =
  | { type: 'ok'; value: T }
  | { type: 'err'; error: E };

export const ok = <T>(value: T): Result<T, never> => ({
  type: 'ok',
  value,
});

export const err = <E>(error: E): Result<never, E> => ({
  type: 'err',
  error,
});

export function isOk<T, E>(r: Result<T, E>): r is { type: 'ok'; value: T } {
  return r.type === 'ok';
}

export function isErr<T, E>(r: Result<T, E>): r is { type: 'err'; error: E } {
  return r.type === 'err';
}

export const map = <T, E, U>(
  r: Result<T, E>,
  fn: (value: T) => U
): Result<U, E> => {
  if (isOk(r)) {
    return ok(fn(r.value));
  }
  return err(r.error) as Result<U, E>;
};

export const unwrapOr = <T, E>(
  r: Result<T, E>,
  defaultValue: T
): T => {
  if (isOk(r)) {
    return r.value;
  }
  return defaultValue;
};
