export type DeepPartial<T> = {
  [P in keyof T]?: T[P] extends (infer U)[]
    ? DeepPartial<U>[]
    : T[P] extends object
    ? DeepPartial<T[P]>
    : T[P];
};

export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  if (patch === null || typeof patch !== 'object') {
    return patch as unknown as T;
  }

  // Handle Arrays: Replace wholesale
  if (Array.isArray(patch)) {
    return patch as unknown as T;
  }

  const result = { ...base } as any;

  for (const key in patch) {
    if (Object.prototype.hasOwnProperty.call(patch, key)) {
      const patchValue = patch[key];

      if (patchValue === undefined) {
        continue;
      }

      const baseValue = (base as any)[key];

      if (patchValue !== null && typeof patchValue === 'object' && !Array.isArray(patchValue)) {
        // Recursive merge for objects
        if (baseValue !== null && typeof baseValue === 'object' && !Array.isArray(baseValue)) {
          result[key] = applyPatch(baseValue, patchValue as DeepPartial<any>);
        } else {
          result[key] = applyPatch(patchValue as DeepPartial<any>, patchValue as DeepPartial<any>);
        }
      } else {
        // Primitive or Array replacement
        result[key] = patchValue;
      }
    }
  }

  return result as T;
}
